"""Unit 26: Tagalog Basic Course, Semester I, Chapter 8, Lesson 1: Religious Holidays.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (piloting edition, September 2017).
Pictures, audio, partner work and role plays are left out; the book's answer keys are used (misprints noted),
percentages, dates and times are written in words in the spoken lines."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


# ------------------------------------------------------------------ 1 Sitti's blog
_BLOG = [("Sa mga Muslim, mahalagang-mahalaga ang pagdiriwang ng Eid al-Fitr o Hari Raya Puasa.", "For Muslims, the celebration of Eid al-Fitr or Hari Raya Puasa is very important."), ("Pagtatapos ito ng isang buwang pag-aayuno, o Ramadan.", "It is the end of a month of fasting, or Ramadan."), ("Araw ng pasasalamat din ito kay Allah.", "It is also a day of thanksgiving to Allah."), ("Bisperas pa lang ng Hari Raya, nagdadasal na kami sa moske.", "Already on the eve of Hari Raya, we pray at the mosque."), ("Tumatagal nang tatlong araw ang pagdiriwang ng Eid.", "The Eid celebration lasts three days."), ("Sama-sama kaming lahat sa kapistahan ng Eid.", "We are all together at the Eid feast."), ("Sa mismong araw ng Hari Raya, sabay-sabay kaming mag-anak na pumupunta ng moske at nagdadasal.", "On the very day of Hari Raya, our whole family goes to the mosque together at the same time and prays."), ("Abalang-abala ang lahat sa paghahanda ng masasarap na pagkain.", "Everyone is very busy preparing delicious food."), ("May mga regalo rin para sa mga kaibigan at kamag-anak.", "There are also gifts for friends and relatives."), ("Sunud-sunod ding dumarating ang mga bisita.", "The guests also arrive one after another.")]
