        + [F("Mahalagang-___ ang pagdiriwang ng Eid. (very important)", "mahalaga", ["abala", "haba"], "mahalagang-mahalaga."), F("___ ang lahat sa paghahanda. (very busy)", "Abalang-abala", ["Sama-sama", "Sunud-sunod"], "abalang-abala."), F("Sunud-sunod ding ___ ang mga bisita. (arrive)", "dumarating", ["nagdadasal", "tumatagal"], "dumarating."), F("Araw ng pasasalamat din ito kay ___. (Allah)", "Allah", ["Hadja", "Pasko"], "Allah."), F("Meron bang ___ si Hadja Normina? (said)", "sinabi", ["ginawa", "balak"], "sinabi."), F("___ pa akong ginawa. (nothing yet)", "Wala", ["Meron", "Mayroon"], "wala pa.")]
