_LA = [("Mahabang-mahaba ang Pasko sa Pilipinas.", "Christmas in the Philippines is very long."), ("Simula Setyembre hanggang Disyembre.", "From September to December."), ("Ang dami-daming regalo para sa kapamilya at inaanak.", "There are so many gifts for family and godchildren."), ("Magandang-maganda ang mga parol sa mga bahay.", "The lanterns on the houses are very beautiful."), ("Sama-samang nagsisimba ang bawat pamilya sa araw ng Pasko.", "Each family attends mass together on Christmas Day."), ("May salu-salo sa noche buena.", "There is a feast on Noche Buena."), ("Masayang-masaya rin ang putukan tuwing Bagong Taon.", "The fireworks every New Year are also very merry."), ("Minu-minuto naming naririnig ang putukan.", "We hear the fireworks every minute."), ("Sari-saring panregalo at pake-paketeng paputok ang ibinebenta.", "Assorted gifts and firecrackers by the pack are sold."), ("Kakaiba rin ang pagdiriwang ng Undas.", "The celebration of Undas is also unique."), ("Sama-samang pumupunta sa sementeryo ang bawat pamilya.", "Each family goes to the cemetery together."), ("May kumakain, nagkakantahan at nagkukuwentuhan.", "Some eat, sing together and tell stories."), ("Iba’t-ibang klaseng bulaklak at kandila ang makikita sa mga puntod.", "Different kinds of flowers and candles can be seen on the graves."), ("Walang-walang sinabi ang Pasko at Undas sa Amerika sa Pilipinas.", "Christmas and Undas in America cannot hold a candle to those in the Philippines.")]
