        + [F("___ ang Pasko sa Pilipinas. (very long)", "Mahabang-mahaba", ["Masayang-masaya", "Magandang-maganda"], "mahabang-mahaba."), F("Magandang-___ ang mga parol sa mga bahay. (beautiful)", "maganda", ["masaya", "mahaba"], "magandang-maganda."), F("Sama-samang ___ ang bawat pamilya sa araw ng Pasko. (attends mass)", "nagsisimba", ["nagdadasal", "tumatagal"], "nagsisimba."), F("May ___ sa noche buena. (feast)", "salu-salo", ["putukan", "kandila"], "salu-salo."), F("Minu-___ naming naririnig ang putukan. (every minute)", "minuto", ["gabi", "araw"], "minu-minuto."), F("May ___ ba sa bahay mamaya? (someone to watch)", "magbabantay", ["nag-imbita", "darating"], "magbabantay.")]
